SELECT , c.cust_no, c.cust_name, c.unified_credit_code, c.main_manager_id, c.main_org_id, CASE WHEN c.is_account_opened = 1 THEN 'OPENED' WHEN c.is_account_opened = 0 THEN 'NOT_OPENED' ELSE 'UNKNOWN' END AS account_opened FROM MARKETING_CUSTOMER_TAG_REL r JOIN MARKETING_CUSTOMER_INFO c ON c.id = r.cust_id WHERE r.tag_id = #{tagId} AND r.active = 1 AND c.record_status = 'ACTIVE'
AND (c.cust_name LIKE CONCAT('%', #{keyword}, '%') OR c.unified_credit_code = #{keyword} OR c.cust_no = #{keyword})
ORDER BY r.effective_time DESC, r.id DESC LIMIT #{offset}, #{limit}

